/**
 * React coding labs: the learner's JSX runs with real React inside a Web Worker (see lab/react-runtime.js), so an
 * endless loop cannot freeze the page. The worker script is generated by scripts/build-react-lab.mjs.
 */
import workerUrl from './reactLab.gen.js?url';
import type { LabRun, LabTest } from './devLab';

export function runReactLab(setup: string, code: string, tests: LabTest[], timeoutMs = 8000): Promise<LabRun> {
  return new Promise((resolve) => {
    let worker: Worker;
    try {
      worker = new Worker(workerUrl);
    } catch {
      resolve({ error: "Brauzer kodni ishga tushira olmadi (Web Worker mavjud emas)", tests: [], logs: [] });
      return;
    }
    const finish = (run: LabRun) => {
      window.clearTimeout(timer);
      worker.terminate();
      resolve(run);
    };
    const timer = window.setTimeout(() => finish({ timedOut: true, error: "Kod juda uzoq ishladi (cheksiz render yoki sikl bo'lishi mumkin)", tests: [], logs: [] }), timeoutMs);
    worker.onmessage = (e: MessageEvent<LabRun>) => finish(e.data);
    worker.onerror = (e) => finish({ error: e.message || 'Xatolik', tests: [], logs: [] });
    worker.postMessage({ setup, code, tests });
  });
}

/** The rendered component as a page for the preview frame. */
export function reactDocument(html: string): string {
  const style = 'body{font:15px/1.5 system-ui,sans-serif;margin:16px;color:#111;background:#fff}button,input,select,textarea{font:inherit;padding:6px 10px;margin:2px;border:1px solid #bbb;border-radius:8px}button{background:#eef;cursor:pointer}li{margin:2px 0}.active{font-weight:700;color:#3730a3}';
  return `<!doctype html><meta charset="utf-8"><style>${style}</style>${html}`;
}
